import{_ as t,o as a,c as n,a0 as i}from"./chunks/framework.BQGW-Zpy.js";const u=JSON.parse('{"title":"Payee Verification & Failed Settlement","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/payee-verification.md","filePath":"architecture/payee-verification.md"}'),s={name:"architecture/payee-verification.md"};function o(r,e,d,c,h,l){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="payee-verification-failed-settlement" tabindex="-1">Payee Verification &amp; Failed Settlement <a class="header-anchor" href="#payee-verification-failed-settlement" aria-label="Permalink to &quot;Payee Verification &amp; Failed Settlement&quot;">​</a></h1><p>Two open questions any real remittance product has to answer. Both have real, standard industry answers, neither is something we invent.</p><h2 id="does-the-destination-account-name-match-the-recipient" tabindex="-1">Does the destination account name match the recipient? <a class="header-anchor" href="#does-the-destination-account-name-match-the-recipient" aria-label="Permalink to &quot;Does the destination account name match the recipient?&quot;">​</a></h2><p>This is a solved problem with a name: <strong>Confirmation of Payee (CoP)</strong> in the UK, and <strong>Verification of Payee (VoP)</strong> as an EU-wide mandate taking effect in 2026 under the EPC VoP Rulebook. Before a transfer is sent, the account name and IBAN/sort code are submitted to the <strong>receiving bank</strong>, which returns one of:</p><table tabindex="0"><thead><tr><th>Result</th><th>Meaning</th><th>Our handling</th></tr></thead><tbody><tr><td><code>matched</code></td><td>Name and account align exactly</td><td>Proceed automatically</td></tr><tr><td><code>partial_match</code></td><td>Close but not exact (e.g. &quot;J. Smith&quot; vs &quot;John Smith Ltd&quot;)</td><td>Show the discrepancy, let the sender confirm or correct</td></tr><tr><td><code>not_matched</code></td><td>Details don&#39;t correspond to the account</td><td>Block the transfer; ask for corrected recipient details</td></tr><tr><td><code>unavailable</code></td><td>The receiving bank doesn&#39;t support the check</td><td>Proceed, flagged as unverified</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This check happens <strong>between banks</strong>, only a party with a banking relationship can query it. That means it is performed by our <strong>licensed payout partner</strong>, not by us. We display the result; we don&#39;t (and structurally can&#39;t) perform the check ourselves. This is the same non-custodial boundary as everywhere else in this architecture.</p></div><h2 id="what-happens-if-the-destination-bank-doesn-t-accept-the-funds" tabindex="-1">What happens if the destination bank doesn&#39;t accept the funds? <a class="header-anchor" href="#what-happens-if-the-destination-bank-doesn-t-accept-the-funds" aria-label="Permalink to &quot;What happens if the destination bank doesn&#39;t accept the funds?&quot;">​</a></h2><p>A transfer can fail after our settlement leg has already completed, the account may be closed, the CoP/VoP check may return <code>not_matched</code>, or the receiving bank may reject the payout for its own reasons. This needs a state the transfer can sit in, rather than silently disappearing or being reported as delivered when it wasn&#39;t.</p><h3 id="proposed-state-payout-failed-reconciliation" tabindex="-1">Proposed state: <code>payout_failed_reconciliation</code> <a class="header-anchor" href="#proposed-state-payout-failed-reconciliation" aria-label="Permalink to &quot;Proposed state: \`payout_failed_reconciliation\`&quot;">​</a></h3><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stateDiagram-v2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PAYOUT_PROCESSING --&gt; COMPLETED: success</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PAYOUT_PROCESSING --&gt; PAYOUT_FAILED_RECONCILIATION: partner reports failure</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PAYOUT_FAILED_RECONCILIATION --&gt; PAYOUT_PROCESSING: sender corrects recipient details (retry)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PAYOUT_FAILED_RECONCILIATION --&gt; REFUNDED: sender requests refund</span></span></code></pre></div><p>The stablecoin leg to the licensed partner may have already settled by this point, that&#39;s a separate concern from whether the <em>final</em> fiat leg succeeded, which is exactly why this needs its own explicit state rather than being folded into &quot;completed&quot; or silently retried.</p>`,11)])])}const m=t(s,[["render",o]]);export{u as __pageData,m as default};
